mapper.update:
UPDATE deposit_items
group_name = #{groupName}, name = #{name}, amount = #{amount}, rate = #{rate}, note = #{note}, sort_order = #{sortOrder}, icon = #{icon}, bind_type = #{bindType}, exclude_total = #{excludeTotal}, item_type = #{itemType}, repayment_day = #{repaymentDay}, payment_account_id = #{paymentAccountId}, repayment_mode = #{repaymentMode},
WHERE id = #{id}

mapper.select:
SELECT id, name, amount, payment_account_id FROM deposit_items
WHERE item_type = 'debt' AND repayment_mode = 'auto' AND repayment_day = #{repaymentDay}
  AND payment_account_id IS NOT NULL AND payment_account_id != ''
